use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

/// Minimal percent-encoding for a query-string value. No dependencies are
/// available, so we encode anything that is not an unreserved URL character.
fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push_str(&format!("{:02X}", b));
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Extended grant: fetch an enrichment record for the input. The input
        // carries no free-text field of its own, so `date` is the input's text
        // here. Use `fetch` so a transport failure is a value we can ignore —
        // the enrichment must not alter the node's output.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&published.date)
        );
        let _ = http_client::fetch(&url);

        // Record every considered id as seen in the read-write 'seen' store.
        let mut recorded: u32 = 0;
        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
            }
            recorded = recorded.saturating_add(1);
        }

        // ensures recorded >= 0 holds trivially for u32.
        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
